tring // \"CASH\", \"CARD\", \"MFS\", \"DUE\"\n  isDue              Boolean @default(false)\n  cashierPerformerId String?\n  notes              String?\n\n  createdAt DateTime @default(now())\n\n  @@index([patientId])\n  @@index([invoiceId])\n  @@index([visitId])\n}\n\n// --------------------------------------------------------\n// CLINIC REAL-TIME INTERNAL CHAT & MESSAGING SYSTEM\n// Partitioned daily by calendar date (dateStr / messageDate)\n// --------------------------------------------------------\n\nmodel ChatMessage {\n  id          String   @id @default(cuid())\n  dateStr     String // e.g. \"2026-10-09\" (Daily partitioned calendar date)\n  messageDate DateTime @default(now())\n  channel     String   @default(\"GENERAL\") // \"GENERAL\", \"CLINICAL\", \"RECEPTION\", \"THERAPY\", \"CASHIER\", or \"DM:userId1:userId2\"\n  content     String // Text only\n  isUrgent    Boolean  @default(false)\n\n  // Sender details\n  senderId      String\n  sender        User       @relation(\"SentChatMessages\", fields: [senderId], references: [id], onDelete: Cascade)\n  senderRole    Role\n  senderName    String\n  performerId   String?\n  performer     Performer? @relation(\"PerformerChatMessages\", fields: [performerId], references: [id], onDelete: SetNull)\n  performerName String?\n\n  // Optional recipient (for 1-on-1 direct staff messages)\n  recipientId   String?\n  recipient     User?   @relation(\"ReceivedChatMessages\", fields: [recipientId], references: [id], onDelete: SetNull)\n  recipientName String?\n\n  // Optional clinical / patient reference\n  patientId   String?\n  patient     Patient? @relation(fields: [patientId], references: [id], onDelete: SetNull)\n  patientName String?\n  roomNumber  String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([dateStr, channel])\n  @@index([dateStr, createdAt])\n  @@index([senderId])\n  @@index([recipientId])\n  @@index([patientId])\n}\n",
